package com.aditya.fefo.controller; import com.aditya.fefo.dto.ProductDtos.*; import com.aditya.fefo.service.ProductService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/products") public class ProductController {private final ProductService s;public ProductController(ProductService s){this.s=s;}@GetMapping public List<ProductResponse> list(){return s.list();}@GetMapping("/{id}") public ProductResponse get(@PathVariable UUID id){return s.get(id);}@PostMapping @PreAuthorize("hasRole('ADMIN')") public ProductResponse create(@Valid @RequestBody CreateProductRequest r){return s.create(r);}}
